import { ChangeDetectionStrategy, Component, OnInit, ViewEncapsulation } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { NzInputNumberModule } from 'ng-zorro-antd/input-number';

import { SFNumberWidgetSchema } from './schema';
import { SFItemWrapComponent } from '../../sf-item-wrap.component';
import { ControlUIWidget } from '../../widget';

@Component({
  selector: 'sf-number',
  template: `<sf-item-wrap
    [id]="id"
    [schema]="schema"
    [ui]="ui"
    [showError]="showError"
    [error]="error"
    [showTitle]="schema.title"
  >
    <nz-input-number
      [nzId]="id"
      [ngModel]="value"
      [ngModelOptions]="{ standalone: true }"
      (ngModelChange)="_setValue($event)"
      [nzDisabled]="disabled"
      [nzSize]="ui.size!"
      [nzVariant]="ui.variant ?? 'outlined'"
      [nzMin]="min"
      [nzMax]="max"
      [nzStep]="step"
      [nzFormatter]="formatter"
      [nzParser]="parser"
      [nzPrecision]="ui.precision ?? null"
      [nzPlaceHolder]="ui.placeholder ?? ''"
      [nzChangeOnWheel]="ui.changeOnWheel ?? true"
      [nzAutoFocus]="ui.autofocus"
      [nzAddonBefore]="ui.addOnBefore!"
      [nzAddonAfter]="ui.addOnAfter!"
      (nzFocus)="focus()"
      (nzBlur)="blur()"
      [style.width]="width"
      [class.ant-input-number__hide-step]="ui.hideStep"
    />
  </sf-item-wrap>`,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, NzInputNumberModule, SFItemWrapComponent]
})
export class NumberWidget extends ControlUIWidget<SFNumberWidgetSchema> implements OnInit {
  min = Number.MIN_SAFE_INTEGER;
  max = Number.MAX_SAFE_INTEGER;
  step!: number;
  formatter?: ((value: number) => string) | null;
  parser?: ((value: string) => number) | null;
  width = '';

  ngOnInit(): void {
    const { minimum, exclusiveMinimum, maximum, exclusiveMaximum, multipleOf, type } = this.schema;
    this.step = multipleOf ?? 1;
    // `exclusiveMinimum` / `exclusiveMaximum` 的语义是「不含边界」，这里按 ± 一个 step 收敛到最近的可选值
    if (typeof minimum !== 'undefined') {
      this.min = exclusiveMinimum ? minimum + this.step : minimum;
    }
    if (typeof maximum !== 'undefined') {
      this.max = exclusiveMaximum ? maximum - this.step : maximum;
    }
    if (type === 'integer') {
      this.min = Math.trunc(this.min);
      this.max = Math.trunc(this.max);
      this.step = Math.trunc(this.step);
    }

    const ui = this.ui;
    // `prefix` 与 `unit` 写的是同一组 formatter/parser，同时配置时 `unit` 覆盖 `prefix`
    if (ui.prefix != null) {
      ui.formatter = value => (value == null ? '' : `${ui.prefix} ${value}`);
      ui.parser = value => +value.replace(`${ui.prefix} `, '');
    }
    if (ui.unit != null) {
      ui.formatter = value => (value == null ? '' : `${value} ${ui.unit}`);
      ui.parser = value => +value.replace(` ${ui.unit}`, '');
    }
    if (ui.formatter) this.formatter = ui.formatter;
    if (ui.parser) this.parser = ui.parser;
    this.width = typeof ui.widgetWidth === 'number' ? `${ui.widgetWidth}px` : (ui.widgetWidth ?? '90px');
  }

  _setValue(val: number): void {
    this.setValue(this.schema.type === 'integer' ? Math.floor(val) : val);
    this.ui.change?.(this.value);
  }

  focus(): void {
    this.ui.focus?.();
  }

  blur(): void {
    this.ui.blur?.();
  }
}
