import { CdkTextareaAutosize } from '@angular/cdk/text-field';
import { ChangeDetectionStrategy, Component, OnInit, ViewEncapsulation } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { NzInputModule } from 'ng-zorro-antd/input';

import { SFTextareaWidgetSchema } from './schema';
import { SFItemWrapComponent } from '../../sf-item-wrap.component';
import { ControlUIWidget } from '../../widget';

@Component({
  selector: 'sf-textarea',
  template: `
    <sf-item-wrap
      [id]="id"
      [schema]="schema"
      [ui]="ui"
      [showError]="showError"
      [error]="error"
      [showTitle]="schema.title"
    >
      @let minRows = autosize?.minRows ?? 1;
      @let maxRows = autosize?.maxRows ?? 0;
      @let variant = ui.variant ?? 'outlined';
      @if (ui.maxCharacterCount) {
        <nz-textarea-count
          [nzMaxCharacterCount]="ui.maxCharacterCount"
          [nzComputeCharacterCount]="ui.computeCharacterCount!"
        >
          <textarea
            nz-input
            [attr.id]="id"
            [disabled]="disabled"
            [attr.disabled]="disabled"
            [nzSize]="ui.size!"
            [ngModel]="value"
            [ngModelOptions]="{ standalone: true }"
            (ngModelChange)="change($event)"
            [attr.maxLength]="schema.maxLength"
            [attr.placeholder]="ui.placeholder"
            cdkTextareaAutosize
            [cdkAutosizeMinRows]="minRows"
            [cdkAutosizeMaxRows]="maxRows"
            [nzVariant]="variant"
            (focus)="focus($event)"
            (blur)="blur($event)"
          >
          </textarea>
        </nz-textarea-count>
      } @else if (ui.allowClear) {
        <nz-input-wrapper [nzAllowClear]="ui.allowClear">
          <textarea
            nz-input
            [attr.id]="id"
            [disabled]="disabled"
            [attr.disabled]="disabled"
            [nzSize]="ui.size!"
            [ngModel]="value"
            [ngModelOptions]="{ standalone: true }"
            (ngModelChange)="change($event)"
            [attr.maxLength]="schema.maxLength"
            [attr.placeholder]="ui.placeholder"
            [nzVariant]="variant"
            (focus)="focus($event)"
            (blur)="blur($event)"
          >
          </textarea>
        </nz-input-wrapper>
      } @else {
        <textarea
          nz-input
          [attr.id]="id"
          [disabled]="disabled"
          [attr.disabled]="disabled"
          [nzSize]="ui.size!"
          [ngModel]="value"
          [ngModelOptions]="{ standalone: true }"
          (ngModelChange)="change($event)"
          [attr.maxLength]="schema.maxLength"
          [attr.placeholder]="ui.placeholder"
          cdkTextareaAutosize
          [cdkAutosizeMinRows]="minRows"
          [cdkAutosizeMaxRows]="maxRows"
          [nzVariant]="variant"
          (focus)="focus($event)"
          (blur)="blur($event)"
        >
        </textarea>
      }
    </sf-item-wrap>
  `,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CdkTextareaAutosize, FormsModule, NzInputModule, SFItemWrapComponent]
})
export class TextareaWidget extends ControlUIWidget<SFTextareaWidgetSchema> implements OnInit {
  autosize?: {
    minRows?: number;
    maxRows?: number;
  };

  ngOnInit(): void {
    if (this.ui.autosize != null) {
      this.autosize = this.ui.autosize;
    }
    if (this.ui.computeCharacterCount == null) {
      this.ui.computeCharacterCount = v => v.length;
    }
  }

  change(val: string): void {
    this.setValue(val);
    this.ui.change?.(val);
  }

  focus(e: FocusEvent): void {
    this.ui.focus?.(e);
  }

  blur(e: FocusEvent): void {
    this.ui.blur?.(e);
  }
}
